@Component("campaignMember-handler")
@ProcessingGroup("campaignMember-processing-group")
public class CampaignMemberEventHandler {
	
	// core constructor
	CampaignMemberEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCampaignMemberEvent
     */
    @EventHandler
    public void handle( CreateCampaignMemberEvent event) {
        entityManager.persist(new CampaignMember(event.getCampaignMemberId(), event.getResponded(), event.getCampaign(), event.getLead(), event.getContact(), event.getStatus(), event.getMemberType()));
    }

    /*
     * @param	event UpdateCampaignMemberEvent
     */
    @EventHandler
    public CampaignMember handle( UpdateCampaignMemberEvent event) {
    	entityManager.merge(new CampaignMember(event.getCampaignMemberId(), event.getResponded(), event.getCampaign(), event.getLead(), event.getContact(), event.getStatus(), event.getMemberType()));
    }
    
    /*
     * @param	event DeleteCampaignMemberEvent
     */
    @EventHandler
    public void on( DeleteCampaignMemberEvent event) {
    	CampaignMember entity = new CampaignMember();
   
    	// ------------------------------------------
    	// apply the CampaignMemberId
    	// ------------------------------------------
    	entity.setCampaignMemberId( event.getCampaignMemberId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CampaignMemberRepository campaignMemberEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CampaignMemberEventHandler.class.getName());

}
